\label{dfn:z2thurstonnorm}
    Let $M$ be a compact $3$-manifold. The $\mathbb{Z}_2$-Thurston norm is a function $||\cdot||_{\mathbb{Z}_2}:H_2(M;\mathbb{Z}_2)\rightarrow \mathbb{Z}^{\geq 0}$ defined by the following expression for each $x\in H_2(M;\mathbb{Z}_2)$ where $\Sigma$ runs over all unoriented surfaces properly embedded in $M$ that represent $x$.

    \[||x||_{\mathbb{Z}_2} := \min_{[\Sigma]=x}\chi_-(\Sigma)\]

\label{dfn:foldedsurface}
    A \textit{folded surface} is a compact 2-dimensional polyhedron and sub-polyhedron pair $(X,\operatorname{\text{Sing}}(X))$ with the following properties:

    \begin{itemize}
        \item \textit{The singular locus}, $\operatorname{\text{Sing}}(X)$ is a compact $1$-manifold. 
        \item \textit{The interior}, $\operatorname{\text{Int}}(X) = X\setminus \operatorname{\text{Sing}}(X)$ is a $2$-manifold.
        \item Every point $p$ in $\operatorname{\text{Sing}}(X)$ has a neighbourhood in $X$ homeomorphic to $\mathbb{R}\times K_{k,1}$ where $p = (0,v)$, $K_{k,1}$ is the cone on $k>0$ univalent vertices, with a single $k$-valent cone vertex $v$. This is homeomorphic to $k$ upper half planes identified along a common $x$-axis on which $p$ lies. We refer to components of $\operatorname{\text{Sing}}(X)$ as \textit{singular arcs}.
    \end{itemize}
    An \textit{oriented} folded surface is a folded surface $X$ with an orientation on $\operatorname{\text{Int}}(X)$.

\label{dfn:pfoldedsurface}
    A \textit{$\mathbb{Z}_p$-folded surface} is an oriented folded surface from Definition~\ref{dfn:foldedsurface} with two additional properties:
    \begin{itemize}
        \item Every point of $\operatorname{\text{Sing}}(X)$ has a neighbourhood in $X$ homeomorphic to $\mathbb{R}\times K_{p,1}$. 
        \item The orientation of $X_{cut}$ induces an orientation of $\partial{X_{cut}}$ on the boundary and let $[\partial{X_{cut}}]\in H_1(\partial{X_{cut}};\mathbb{Z})$ be the corresponding fundamental class. The quotient map $q:X_{cut}\rightarrow X$ restricts to a map $\partial{X_{cut}}\rightarrow \operatorname{\text{Sing}}(X)$ inducing a homomorphism $H_1(\partial{X_{cut}};\mathbb{Z})\rightarrow H_1(\operatorname{\text{Sing}}(X);\mathbb{Z})$. There exists a unique orientation of $\operatorname{\text{Sing}}(X)$ such that if $[\operatorname{\text{Sing}}(X)]\in H_1(\operatorname{\text{Sing}}(X);\mathbb{Z})$ is the corresponding fundamental class then the induced homomorphism sends $[\partial{X_{cut}}] \mapsto p\cdot [\operatorname{\text{Sing}}(X)]$. In other words the $p$ sheets incident to each arc of the singular locus all induce a consistent orientation along their identified boundaries. 
    \end{itemize}

\label{lem:alternatedefinition}
    An oriented folded surface $X$ is a $\mathbb{Z}_p$-folded surface if and only if there exists an orientation of $\operatorname{\text{Sing}}(X)$ such that:
    \begin{enumerate}
        \item $\sum_{B \in \pi_0(q^{-1}(K))} \deg(q_B) = p$ for all $K\in \pi_0(\operatorname{\text{Sing}}(X))$. \label{altdef:sumdegp}
        \item $\deg(q_B)>0$ for all $B\in \pi_0(\partial X_{cut})$. \label{altdef:degpositive}
    \end{enumerate}

\label{def:assocgraph}
    Let $G(X) := (I,S,E,\phi,\psi,d,g)$ be the $p$-fold graph where:
    \begin{itemize}
        \item $I := \pi_0(X_{cut})$
        \item $S := \pi_0(\operatorname{\text{Sing}}(X))$
        \item $E = \pi_0(\partial X_{cut})$, 
        \item For every boundary component $B$ of $X_{cut}$ define the following:
        \begin{itemize}
            \item $\phi(B)$ is the unique component of $X_{cut}$ which cobounds $B$
            \item $\psi(B) := q_B(B) \in \pi_0(\operatorname{\text{Sing}}(X))$
            \item $d(B):= \deg(q:B\rightarrow q(B))$
        \end{itemize}
        \item For every component $Y$ of $X_{cut}$ let $g(Y)$ be the (orientable) genus of $Y$.
    \end{itemize}

\label{dfn:zpthurstonnorm}
    Let $M$ be a closed $3$-manifold. For each $p\in \mathbb{Z}^{>0}$ the $\mathbb{Z}_p$-Thurston norm is a function $||\cdot||_{\mathbb{Z}_p}:H_2(M;\mathbb{Z}_p)\rightarrow \mathbb{Z}^{\geq 0}$ defined for each class $x \in H_2(M;\mathbb{Z}_p)$ by the following expression, allowing $X$ to run over all $\mathbb{Z}_p$-folded surfaces embedded in $M$ that realise $x$:

    \[||x||_{\mathbb{Z}_p} := \min_{[X]=x}(\chi_-(X))\]

\label{lem:thurstonnorm}
    For all $x\in H_2(M;\mathbb{Z}_p)$ where $M$ is a $3$-manifold Equation~\eqref{eq:zpthurstonzthurston} holds, where $L$ denotes an oriented link embedded in $M$ and $F$ is defined in Equation~\ref{eq:defofF}.

    \begin{equation}\label{eq:zpthurstonzthurston}
        ||x||_{\mathbb{Z}_p} = \min_{[L]=d_{\mathbb{Z}_p}(x)} \left(\min_{y\in F(x,L)} ||e(y)||_{\mathbb{Z}} \right)
    \end{equation}

Let $X$ be a $\mathbb{Z}_p$-folded surface embedded in $M$ via a map $f:X\hookrightarrow M$. To avoid confusion in this proof we avoid all abuses of notation by using $[X]$ and to denote the fundamental class of $X$ and $f_*([X])$ to denote the class in $H_2(M;\mathbb{Z}_p)$ it represents. Suppose $f_*([X]) = x$ and $\chi_{-}(X) = ||x||_{\mathbb{Z}_p}$. 

    First let $L := f(\operatorname{\text{Sing}} X)$. Equation~\eqref{eq:pSingXfromdef} shows that $[L] = d_{\mathbb{Z}_p}(x)$ using the naturality of the coefficient long exact sequence.

    \begin{equation}
        \label{eq:pSingXfromdef}
        \begin{aligned}
            d_{\mathbb{Z}_p}(x) &= d_{\mathbb{Z}_p} \circ f_*([X]) \\
                &= f_* \circ d_{\mathbb{Z}_p}([X]) \\
                &= f_*([\operatorname{\text{Sing}} X]) \\
                &= [f(\operatorname{\text{Sing}} X)]\\
                &= [L]
        \end{aligned}
    \end{equation}

    Now let $y' := f_*\circ q_*([X_{cut}]) \in H_2(M,L;\mathbb{Z})$. $e(y')$ is represented by the properly embedded oriented $2$-manifold $\Sigma := f\circ q(X_{cut}) \setminus N(L)$. $\Sigma$ is homeomorphic to $X_{cut}$ and $\chi_-(X_{cut}) = \chi_-(X)$ by definition. Hence $||e(y')|| \leq \chi_-(\Sigma) = \chi_-(X) = ||x||_{\mathbb{Z}_p}$. 

    We now claim that $y'\in F(x,L)$. It follows from the definition in Equation~\eqref{eq:defofF} that it is sufficient to show that $y'$ satisfies Claims~\eqref{cl:claim1} and~\eqref{cl:claim2}.

    \begin{equation}\label{cl:claim1}
        j_{\mathbb{Z}_p}(y') = j_{(M,L)}(x)
    \end{equation}

    \begin{equation}\label{cl:claim2}
        d_{(M,L)}(y') = p[L]
    \end{equation}

    First note that $j_{\mathbb{Z}_p}(y') = j_{\mathbb{Z}_p}\circ f_*\circ q_*([X_{cut}]) = f_* \circ j_{\mathbb{Z}_p} \circ q_*([X_{cut}])$ by naturality of the coefficient long exact sequence. It follows from the definition of $[X]$ in Section~\ref{sec:realisation} that $j_{(X,\operatorname{\text{Sing}} X)}([X]) = j_{\mathbb{Z}_p} \circ q_*([X_{cut}])$. Hence we obtain $j_{\mathbb{Z}_p}(y') = f_*\circ j_{(X,\operatorname{\text{Sing}} X)}([X])$. It follows from the naturality of the long exact sequences of the pairs under the map $(X,\operatorname{\text{Sing}} X)\xrightarrow{f} (M,L)$ implies that $f_*\circ j_{(X,\operatorname{\text{Sing}} X)} = j_{(M,L)} \circ f_*$ and so we have $j_{\mathbb{Z}_p}(y') =j_{(M,L)} \circ f_*([X]) = j_{(M,L)}(x)$. This proves Claim~\eqref{cl:claim1}.

    The same relation $f_*\circ j_{(X,\operatorname{\text{Sing}} X)} = j_{(M,L)} \circ f_*$ also implies that $d_{(M,L)}(y') = d_{(M,L)} \circ f_*\circ q_*([X_{cut}]) = f_* \circ d_{(X,\operatorname{\text{Sing}} X)} \circ q_*([X_{cut}])$. The naturality of the long exact sequences of the pairs under the map $(X_{cut},\partial X_{cut})\xrightarrow{q} (X,\operatorname{\text{Sing}} X)$ implies that $d_{(X,\operatorname{\text{Sing}} X)} \circ q_* = q_* \circ d_{(X_{cut},\partial X_{cut})}$. Hence we have $d_{(M,L)}(y') = f_* \circ q_* \circ d_{(X_{cut},\partial X_{cut})}([X_{cut}])$. $[X_{cut}]$ is the fundamental class of a compact orientable $2$-manifold and so if $\partial X_{cut}$ is endowed with the induced orientation it follows that $d_{(X_{cut},\partial X_{cut})}([X_{cut}]) = [\partial X_{cut}]$. Moreover, it follows from Definition~\ref{dfn:pfoldedsurface} that $q_*([\partial X_{cut}]) = p[\operatorname{\text{Sing}} X]$ and so $d_{(M,L)}(y') = f_*(p[\operatorname{\text{Sing}} X]) = p[f(\operatorname{\text{Sing}} X)] = p[L]$. This proves Claim~\eqref{cl:claim2}.

    Since we have shown that $[L] = d_{\mathbb{Z}_p}(x)$, $y'\in F(x,L)$ and $||x||_{\mathbb{Z}_p} \geq ||e(y')||$. Combining these yields Equation~\eqref{eq:combiningfacts}.

    \begin{equation}\label{eq:combiningfacts}
        ||x||_{\mathbb{Z}_p} \geq ||e(y')|| \geq \min_{[L]=d_{\mathbb{Z}_p}(x)} \left(\min_{y\in F(x,L)} ||e(y)||_{\mathbb{Z}} \right)
    \end{equation}


    We will now prove the opposite inequality. Let $L$ be an oriented link and $y\in F(x,L)$ such that $||y||$ minimises the right hand side of the statement in Lemma~\ref{lem:thurstonnorm}. Let $S$ be a properly embedded oriented surface in $M \setminus N(L)$ such that $[S] = y$ and $\chi_-(S) = ||y||$. The two surgeries described in the proof of Lemma~\ref{lem:existence} required to make $S$ homeomorphic to the interior of a $\mathbb{Z}_p$-folded surface can be described simply as gluing disks and annuli to the boundary components of $S$ in an orientation preserving way. If we cap off a boundary component of a connected component $S_i$ of $S$ with a disk to form a new component $S_i'$ of $S'$ then $\chi(S') = \chi(S)+1$ with all other components the same so $\chi_{-}(S')\leq \chi_{-}(S)$ and by the minimality of $\chi_{-}(S)$ we have $\chi_{-}(S') = \chi_{-}(S)$. If we glue an annulus to two boundary components of the same component $S_i$ of $S$ then $\chi(S_i') = \chi(S_i)$ and so $\chi_{-}(S) = \chi_{-}(S')$. Finally if we glue an annulus joining boundary components of distinct components $S_i$ and $S_j$ of $S$ to form $S_{ij}'$ and $S'$ then $\chi(S_{ij}') = \chi(S_i)+\chi(S_j)$. If $\chi(S_i) < 0 < \chi(S_j)$ or vice-versa then $\chi_{-}(S')< \chi_{-}(S)$ which contradicts the minimality of $\chi_{-}(S)$, so this cannot happen. The remaining cases are that both components are disks, both have negative Euler characteristic or one of them is an annulus. In all three cases it follows that $\chi_{-}(S_{ij}') = \chi_{-}(S_i)+ \chi_{-}(S_j)$ and so $\chi_{-}(S') = \chi_{-}(S)$. Combining this observation with the rest of the proof of Lemma~\ref{lem:existence} shows that we can construct a $\mathbb{Z}_p$-folded surface $X$ realising $x$ such that $||x||_{\mathbb{Z}_p} \leq \chi_{-}(X) = \chi_{-}(S) = ||y||$. This yields Equation~\eqref{eq:combiningfacts2}.

    \begin{equation}\label{eq:combiningfacts2}
        ||x||_{\mathbb{Z}_p} \leq \min_{[L]=d_{\mathbb{Z}_p}(x)} \left(\min_{y\in F(x,L)} ||e(y)||_{\mathbb{Z}} \right)
    \end{equation}

    Combining Equations~\eqref{eq:combiningfacts} and~\eqref{eq:combiningfacts} completes the proof.

\label{lem:weightedfoldedalternatedef}
    A weighted folded surface $X$ is a weighted $\mathbb{Z}_p$-folded surface if and only if there exists an orientation of $\operatorname{\text{Sing}}(X)$ with the following properties.
    \begin{enumerate}
        \item $\deg(B \xrightarrow{q_{\underline{X}}} q_{\underline{X}}(B))>0$ for all $B\in \pi_0(\partial \underline{X}_{cut})$.
        \item Let $X_{B}$ denote the unique component of $\operatorname{\text{Int}} X$ such that the lift of $X_B$ to $X_{cut}$ cobounds $B$. Then $\sum_{B \in \pi_0(q^{-1}(K))} w_{X_B} \cdot \deg(B \xrightarrow{q_{\underline{X}}} K) = p$ for all $K\in \pi_0(\operatorname{\text{Sing}}(X))$.
    \end{enumerate}

\label{lem:weightedpfoldedsurfaces}
    Let $X$ be a weighted $\mathbb{Z}_p$-folded surface embedded in a connected orientable 3-manifold $M$. There exists another weighted $\mathbb{Z}_p$-folded surface $Y$ with the following properties.
    \begin{enumerate}
        \item $[Y] = [X]$
        \item $\chi_-(Y^u)\leq \chi_-(X^u)$
        \item $|\operatorname{\text{Sing}}(\underline{Y})| = |\operatorname{\text{Sing}}(\underline{X})|$
        \item $M\setminus \underline{Y}$ is connected
    \end{enumerate}

    Moreover, for any $x \in H_2(M;\mathbb{Z}_p)$ there exists a weighted $\mathbb{Z}_p$-folded surface $X$ such that $[X]=x$, $||x||_{\mathbb{Z}_p} = \chi_{-}(X^u)$ and $M\setminus \underline{X}$ is connected.

\label{lem:injectivitynonsep}


    Let $Y$ be a 2-polyhedron embedded in a closed orientable connected 3-manifold $M$. The following are equivalent:
    \begin{enumerate}
        \item $Y$ is non-separating in $M$. \label{enum:nonseparating}
        \item The induced homomorphism $f_{\mathbb{Z}}:H_2(Y;\mathbb{Z})\rightarrow H_2(M;\mathbb{Z})$ is injective. \label{enum:Zinjective}
        \item The induced homomorphism $f_{\mathbb{Z}_p}:H_2(Y;\mathbb{Z}_p)\rightarrow H_2(M;\mathbb{Z}_p)$ is injective for all $p\in \mathbb{Z}^{>1}$. \label{enum:Zkinjective}
    \end{enumerate}

\label{lem:noremovabledisks}

    Let $X$ be a weighted non-separating $\mathbb{Z}_p$-folded surface with a removable disk $D$ component of $\operatorname{\text{Int}}(X)$. There exists another weighted non-separating $\mathbb{Z}_p$-folded surface $Y$ such that:

    \begin{enumerate}
        \item $[X] = [Y]$
        \item $\chi_-(Y^u)\leq \chi_-(X^u)$
        \item $|\pi_0(\operatorname{\text{Sing}}(Y^u))| = |\pi_0(\operatorname{\text{Sing}}(X^u))|-1$
        \item $\chi(Y^u) = \chi(X^u) + p - 2w_D$
        \item $\max_{C\in \pi_0(\operatorname{\text{Int}}(\underline{Y}))} w_C \leq \max_{C\in \pi_0(\operatorname{\text{Int}}(\underline{X}))} w_C$
    \end{enumerate}

If $w_D = p$ then the closure of $D$ in $X$ is a connected component of $X$ which we denote $X_D$. $X_D$ represents a trivial homology class in $M$ since it embeds in a 3-ball regular neighbourhood of $D$. Let $Y$ be the weighted $\mathbb{Z}_p$-folded surface obtained by removing this $X_D$ from $X$. Since $\chi(X_{D}^u) = p$ it follows that $\chi(Y^u) = \chi(X^u) - p = \chi(X^u) +p - 2w_D$ as required. The rest of the requirements of the proof are similarly easy to prove.

    Hence, let $w_D <p$ and let $K = \partial{D}$ be the singular arc along its boundary. There is at least one other component $C$ of $\operatorname{\text{Int}}(X)$ such that $K\subseteq \partial{C}$. Lemma~\ref{lem:classificationin3mflds} and Lemma~\ref{lem:alternatedefinition} together imply that $\deg(B\xrightarrow{q_{\underline{X}}}K) = 1$ for all $B\in \pi_0(q_{\underline{X}}^{-1}(K))$. Let $k$ be the number of boundary components of $\underline{X}_{cut}$ in the preimage of $K$ under $q$. A similar argument to the proof of Lemma~\ref{lem:regularneighbourhoods} implies that the embedding $\underline{X}\cap N \hookrightarrow N$ where $N$ is a regular neighbourhood of $K$ is homeomorphic to the sub-bundle embedding of $K_{k,1}\times S^1 \hookrightarrow \mathbb{D}^2 \times S^1$ that restricts on sections to an embedding $K_{k,1}\hookrightarrow \mathbb{D}^2$ where the image in the unit disk is given by the $k\leq p$ intervals from the origin to $k$ equally spaced points on the unit circle. The interior of exactly one of these intervals is in $D$.

    Now push $D$ in a normal direction relative to $\partial{D}$ to obtain $k-1$ parallel copies $\{D_i\}_{i=1}^{k-1}$ and let $X' = (\underline{X}\setminus D)\cup \bigsqcup_{i=1}^{k-1}D_i$. $X'$ is a folded surface with $2k-2$ sheets meeting along $K$. Now the embedding $X'\cap N\hookrightarrow N$ is homeomorphic to the sub-bundle embedding of $K_{2k-2,1}\times S^1 \hookrightarrow \mathbb{D}^2 \times S^1$ that restricts on sections to an embedding $K_{2k-2,1}\hookrightarrow \mathbb{D}^2$. The image of $K_{2k-2,1}\hookrightarrow \mathbb{D}^2$ in the unit disk is given by the $2k-2$ unit intervals $\{[0,x_j]\}_{j=1}^{2k-2}$ where $x_j := e^{\frac{2i\pi j}{2k-2}}$ and the points $x_i \in D_i$ for all $1\leq i  \leq k-1$ and $x_j\in \operatorname{\text{Int}}(\underline{X})\setminus D$ for all $k - 1<j\leq 2k-2$. Replace $X'\cap N$ with the sub-bundle $\left(\bigsqcup_{i=1}^{k-1} I_i \right)\times S^1 \hookrightarrow \mathbb{D}^2\times S^1$ which is described on sections as the proper embedding of $k-1$ intervals $I_i := [x_i,x_{2k-1-i}]$ in $\mathbb{D}^2$. Orient and weight the components of the resulting folded surface to be consistent with the orientation and weight of the components of $\operatorname{\text{Int}}(\underline{X})$ where they overlap in $M$. Let the resulting weighted folded surface be $Y$. See Figure~\ref{fig:crosssection} for an illustration of the cross-sections of the intersection of $\underline{X},\underline{X'}$ and $\underline{Y}$ with $N$. The complement $M\setminus \underline{Y}$ is connected since it can be obtained from $M \setminus \underline{X}$ by gluing $(k-2)$ 2-handles that lie in the space between $D_i$ and $D_{i+1}$ for $1\leq i\leq k-2$. See Figure~\ref{fig:diskremoval} for a visualisation of an example of this disk removal procedure where $p=11$ and $k=4$.

    $Y$ is a weighted $\mathbb{Z}_p$-folded surface since the weights and orientation of sheets in neighbourhoods of every singular arc other than $K$ are unchanged. It can also be seen from the construction that $\operatorname{\text{Sing}}(Y) = \operatorname{\text{Sing}}(X)\setminus K$. Since $Y$ differs from $X$ only in the interior of a $3$-ball regular neighbourhood $H$ of $D$ it follows that $[X]-[Y] \in \text{Im}(H_2(H;\mathbb{Z}_p) \rightarrow H_2(M;\mathbb{Z}_p))$. Since $H_2(H;\mathbb{Z}_p) = 0$ it follows that $[X] = [Y]$. 

    $Y^u_{cut}$ is homeomorphic to the $2$-manifold obtained from $X^u_{cut}$ by removing $w_D$ copies of $D_{cut}$ and gluing disks to $p-w_D$ boundary components of $X^u_{cut} \setminus D_{cut}$. From this observation Equations~\eqref{eq:chiminusequation} and~\eqref{eq:chiequation} follow from elementary properties of the Euler characteristic.

    \begin{equation}\label{eq:chiminusequation}
        \chi_-(Y^u) = \chi_-(Y^u_{cut}) \leq \chi_-(X^u_{cut}) = \chi_-(X^u)
    \end{equation}

    \begin{equation}\label{eq:chiequation}
        \chi(Y^u) = \chi(Y^u_{cut}) = \chi(X^u)_{cut} - w_D + p-w_D = \chi(X^u_{cut})+ p - 2w_D
    \end{equation}

    The weights of $Y$ are all present among the weights of $X$ by construction. In particular, the maximum weight of $Y$ is bounded by the maximum weight of $X$ from above.

\label{lem:removenotdisks}
    Let $X$ be a weighted non-separating $\mathbb{Z}_p$-folded surface with no removable disks, but a removable component $C$ of $\operatorname{\text{Int}}(\underline{X})$ such that $w_C>p/2$ with $\partial C \neq \emptyset$. There exists another weighted non-separating $\mathbb{Z}_p$-folded surface $Y$ with the following properties.

    \begin{enumerate}
        \item $[X] = [Y]$
        \item $\chi_-(Y^u)\leq \chi_-(X^u)$
        \item $|\pi_0(\operatorname{\text{Sing}}(Y^u))| = |\pi_0(\operatorname{\text{Sing}}(X^u))|- |\pi_0(\partial{C})|$ \label{property:sing}
    \end{enumerate}

\label{lem:surfacecomponents}
    If $X$ is a weighted non-separating $\mathbb{Z}_p$-folded surface and $C$ is a component of $\operatorname{\text{Int}}(X)$ such that $\partial{C} = \emptyset$ and $w_C>p/2$ then there exists another weighted non-separating $\mathbb{Z}_p$-folded surface $Y$ such that:

    \begin{enumerate}
        \item $[X] = [Y]$
        \item $\chi_-(Y^u)\leq \chi_-(X^u)$
        \item $|\pi_0(Y^u)| = |\pi_0(X^u)| - (2w_C - p)$
        \item $X\setminus C = Y\setminus C$ as weighted $\mathbb{Z}_p$-folded surfaces.
    \end{enumerate}

This is essentially a direct consequence of Lemma~\ref{lem:noremovabledisks}, Lemma~\ref{lem:removenotdisks} and Lemma~\ref{lem:surfacecomponents}. We start with a weighted non-separating $\mathbb{Z}_p$-folded surface $X$ such that $[X]=x$ and $\chi_-(X^u) = ||x||_{\mathbb{Z}_p}$ which exists due to Lemma~\ref{lem:weightedpfoldedsurfaces}. The programme is as follows:

    \begin{enumerate}
        \item If $X$ has any removable disks then apply Lemma~\ref{lem:noremovabledisks}. Since 
        \[|\pi_0(\operatorname{\text{Sing}}(\underline{X}))|<\infty,\] 
        it follows that repeatedly applying Lemma~\ref{lem:noremovabledisks} will eventually terminate in a non-separating $\mathbb{Z}_p$-folded surface with no removable disks.\label{step:disks}
        \item If $X$ has any component $C\in \pi_0(\operatorname{\text{Int}}(X))$ such that $w_C>p/2$ and $\partial{C}\neq \emptyset$ then Lemma~\ref{lem:weightp/2} implies that $C$ is removable. Apply Lemma~\ref{lem:removenotdisks}. If the resulting weighted non-separating $\mathbb{Z}_p$-folded surface has any removable disks then apply step~\ref{step:disks} again. \label{step:Cp/2}
        \item Repeatedly apply Step~\ref{step:Cp/2}. It follows from Lemma~\ref{lem:noremovabledisks} and Lemma~\ref{lem:removenotdisks} that each time this is done the number of singular arcs of $X$ is strictly reduced. Eventually this terminates because $|\pi_0(\operatorname{\text{Sing}}(\underline{X}))|<\infty$.
        \item The result of previous steps is a weighted non-separating $\mathbb{Z}_p$-folded surface with no removable disks in which the only components $C$ of $\operatorname{\text{Int}}(\underline{X})$ for which $w_C>p/2$ are closed surfaces in $\underline{X}$. Repeatedly apply Lemma~\ref{lem:surfacecomponents}. This does not affect the number of removable disks or non-surface components with weights greater than $p/2$. $|\pi_0(\underline{X})|<\infty$ and so this will eventually terminate in a weighted non-separating $\mathbb{Z}_p$-folded surface with no removable disks and such that every weight is less than $p/2$.
    \end{enumerate}

    Due to the minimality in the definition of $||\cdot||_{\mathbb{Z}_p}$ we have that the resulting weighted non-separating $\mathbb{Z}_p$-folded surface has the required properties.

\label{conj:lpn1}
    Let $M = L(pn,1)$. Then 
    \[\max \left\{\chi_p(x) : x \in H_2(M;\mathbb{Z}_p)\setminus \{0\}\right\} = 2-n.\]

\label{conj:maxcanonicalischi_p}
    Let $\mathcal{C}$ be the set of all one-vertex triangulations of a closed orientable irreducible $3$-manifold $M$ and let $\varphi \in H^1(M;\mathbb{Z}_p)$. The following holds:
    \[\max_{\mathcal{T}\in \mathcal{C}}\chi(S_{\varphi}(\mathcal{T})) = \chi_p(\varphi^*)\]

\label{lem:surfacerealisation}
    Let $X$ be a $\mathbb{Z}_3$-folded surface embedded in a $3$-manifold $M$ and $x\in H_2(X;\mathbb{Z}_2)$. Let $S(x) := \bigcup_{C\in I(x)} \overline{C}$. The following are true:
    \begin{enumerate}
        \item The set $S(x)\subset X$ is homeomorphic to a closed surface.
        \item The class $x\in H_2(X;\mathbb{Z}_2)$ is the image of the fundamental class of $S(x)$ under the induced map $H_2(S(x);\mathbb{Z}_2)\rightarrow H_2(X;\mathbb{Z}_2)$. 
        \item If $x\in \ker(H_2(X;\mathbb{Z}_2)\rightarrow H_2(M;\mathbb{Z}_2))$ then $S(x)$ is orientable and every component of $I(x)$ is removable.
    \end{enumerate}

\label{lem:surfaceelimination}
    Let $x \in \ker(H_2(X;\mathbb{Z}_2)\rightarrow H_2(M;\mathbb{Z}_2))$ where $X$ is a $\mathbb{Z}_3$-folded surface embedded in $M$. Let $\mathfrak{o}$ be a choice of orientation of $S(x)$ induced by an orientation of a component of its complement in $M$ and denote the opposite choice $-\mathfrak{o}$. Let $I(x,\mathfrak{o}) \subseteq I(x)$ be the components oriented consistently by the orientation of $\operatorname{\text{Int}}(X)$ and $\mathfrak{o}$. Let $X(x,\mathfrak{o})$ be the $\mathbb{Z}_3$-folded surface with underlying set $X \setminus \bigsqcup I(x,\mathfrak{o})$ and the orientation of $\operatorname{\text{Int}}(X(x,\mathfrak{o}))$ which is consistent with the orientation of $\operatorname{\text{Int}}(X)$ on the set $\operatorname{\text{Int}}(X(x,\mathfrak{o})) \setminus \overline{\bigsqcup I(x,-\mathfrak{o})}$ and opposite on the set $\bigsqcup I(x,-\mathfrak{o})$. We say that $X(x,\mathfrak{o})$ is the surface elimination of $x$ with orientation $\mathfrak{o}$. It has the following properties:

    \begin{enumerate}
        \item $[X(x,\mathfrak{o})] = [X]$
        \item If $I(x,\mathfrak{o}) \neq \emptyset$ then $\ker(H_2(X(x,\mathfrak{o});\mathbb{Z}_2)\rightarrow H_2(M;\mathbb{Z}_2))$ is a proper subgroup of $\ker(H_2(X;\mathbb{Z}_2)\rightarrow H_2(M;\mathbb{Z}_2))$ under the inclusion $i_{(X,X(x,\mathfrak{o}))}$
        \item $\chi(X(x,\mathfrak{o})) = \chi(X) - \sum_{C\in I(x,\mathfrak{o})}\chi(C)$
    \end{enumerate}

\label{lem:meridionaldiskintersection}
    For any $\mathbb{Z}_p$-folded surface $X$ embedded in $L(k,q)$ there exists a genus $1$ Heegaard splitting $L(k,q) = S_1\cup S_2$ such that $X\cap S_1$ consists of a finite number $d$ of meridional disks and $(S_1\cap S_2, X\cap S_1\cap S_2)$ is bicollared in $(L(k,q),X)$.
    Moreover if we fix a meridional homology class $\mu_1$ of $S_1$ and let $d_{\pm}$ be the number of disks of $X \cap S_1$ whose boundary (with the induced orientation) realises the class $\pm \mu_1 \in H_1(\partial S_1;\mathbb{Z})$ then the homology class of $[X]$ uniquely determines $d_+ - d_- \mod p$. We will call a genus $1$ Heegaard splitting of this kind \textbf{adapted} to $X$.

\label{lem:transversemeridionaldisk}
    Suppose that $X$ is a $\mathbb{Z}_p$-folded surface embedded in $L(k,q)$ with $S_1\cup S_2$ a genus $1$ Heegaard splitting adapted to $X$ as per Lemma~\ref{lem:meridionaldiskintersection} and $T:= S_1\cap S_2$. There exists an oriented meridional disk $D$ of $S_2$ with the following properties.

    \begin{itemize}
        \item $\partial D$ is mocktransverse to $X\cap T$ in $T$.

        \item $\partial D \cap X$ is a set of $kd$ points with a cyclic order induced by the orientation of $\partial D$. 

        \item Let $\sigma:\partial D \cap X\rightarrow \partial D \cap X$ be the permutation which maps each point to its immediate successor in the cyclic order. For all $b\in \partial D \cap X$ let $M$ be the component of $X\cap S_1$ that contains it. The point $\sigma^d(b)$ lies on the boundary of the same meridional disk $M$ and the sign of the intersection of $\partial M$ with $\partial D$ at both points is the same.

        \item $(D,D \cap X)$ bicollars in $(S_2,S_2\cap X)$.
    \end{itemize}

Let $d$ be the number of meridional disks in $S_1\cap X$. Let $T = S_1\cap S_2$ be the splitting torus. Since $\partial S_1$ and $\partial S_2$ are identified with $T$ in $L(k,q)$ we can interpret $\mu_1,\mu_2,\lambda_1,\lambda_2$ as elements of $H_1(T;\mathbb{Z})$. We first describe $(T,X\cap T, \partial D)$. Since mocktransversality and the sign of intersections are preserved by ambient isotopies it is sufficient to describe curves on $T$ that are ambient isotopic to $X\cap T$ and $\partial D$. To this end consider the triangulation $\mathcal{T}$ of $T$ with one vertex, two triangles and three edges $e_{\lambda_2},e_{\mu_2},e_{\lambda_2+\mu_2}$ which realise the homology classes $\lambda_2,\mu_2, \lambda_2+\mu_2$ respectively when viewed as $1$-cycles when oriented as in Figure~\ref{fig:Ttriangulation}. 

\begin{figure}
    \centering
    \includegraphics[width=0.7\linewidth]{vector-graphics/Ttriangulation.pdf}
    \caption{The distinguished triangulation of $\partial S_2$ and the unique normal meridional curve realising $\mu_1$.}
    \label{fig:Ttriangulation}
\end{figure}

    Standard arguments from the theory of normal curves imply that for each simple closed curve $Y$ embedded in $T$ that does not bound a disk there exists an ambient isotopy of $T$ carrying $Y$ to a curve $Y'$ that is normal with respect to the triangulation $\mathcal{T}$ (see Theorem 3.2.2 of~\cite{matveev:2003} for details of the normalisation procedure). This very simple triangulation $\mathcal{T}$ also has the property that such a normal curve is unique up to normal isotopy. If $Y$ is an oriented simple closed curve then the solution to the matching equations of $\mathcal{T}$ that describes $Y'$ is determined by the Poincar\'e dual $PD([Y])\in H^1(T;\mathbb{Z})$ of the homology class $[Y]\in H_1(T;\mathbb{Z})$ realised by $Y$. To be precise the number of points of intersection of $Y'$ with the edge $e_{\alpha}$ is given by $|PD([Y])(\alpha)|$ for $\alpha \in \{\mu_2,\lambda_2,\mu_2+\lambda_2\}$ where we identify $H^1(T;\mathbb{Z}) = \text{Hom}(H_1(T;\mathbb{Z}),\mathbb{Z})$ via the universal coefficient theorem and $|\cdot|:\mathbb{Z}\rightarrow \mathbb{Z}^{\geq0}$ is the usual absolute value function. $PD(a\mu_2 + b\lambda_2)(c\mu_2+d\lambda_2) = \pm(ad-bc)$ with the $\pm$ depending on a particular choice of Poincar\'e duality map $PD$ or equivalently a fundamental class of $T$.

    Now suppose we have performed an ambient isotopy to $T$ and put $X\cap T$ into a position such that it is normal with respect to $\mathcal{T}$. Each component $\partial M$ of $X\cap T$ is a simple closed curve that inherits an orientation from a corresponding component $M$ of $X\cap S_1$ which cobounds it and so realises the homology class $\pm \mu_1 = \pm(k\lambda_2 + q\mu_2) \in H_1(T;\mathbb{Z})$. The above discussion shows that $\partial M$ intersects $e_{\mu_2}$ in $k$ points, $e_{\lambda_2}$ in $q$ points and $e_{\mu_2+\lambda_2}$ in $k-q$ points (since we assume $k>q$). This normal curve is shown in Figure~\ref{fig:Ttriangulation}. It follows from the intersection form or by an inductive argument following these normal arcs through the triangulation that every intersection of $\partial M$ with the oriented edge $e_{\mu_2}$ must be of the same sign. The required cyclic ordering comes from the fact that there are $d$ such components of $X\cap S_1$ and so the normal curve $X\cap T$ consists of $d$ parallel copies of this normal curve, intersecting $e_{\mu_2}$ in $kd$ points. 

    We now set $\partial D:= e_{\mu_2}$. It follows from Definition~\ref{dfn:mocktransverse} and the properties of normal curves that $\partial D$ is mocktransverse to $X\cap T$.

    $\partial D$ is a meridional curve of $S_2$ and so it cobounds a properly embedded disk $D$ in $S_2$. We now invoke the Relative Mocktransversality Theorem quoted in Theorem~\ref{thm:relmocktransversality} to obtain an ambient isotopy of $S_2$ fixed on $\partial S_2 = T$ that allows us to replace $D$ with a disk that is mocktransverse to $X\cap S_2$ cobounding $\partial D$ as required.

    By definition~\ref{dfn:mocktransverse} there exists a PL cell complex $\mathcal{B}$ of $S_2$ such that $D$ is a subcomplex and to which $X\cap S_2$ is transverse. By dissolving the $3$-cells of this cell complex along the $2$-cells that are not contained in the subcomplex $\partial S_2 \cup D$ we obtain a PL cell complex $\mathcal{C}$ with a single $3$-cell, in which $D$ is a $2$-cell and every other $2$-cell is contained in the boundary torus. The local conditions of transversality are preserved under this cell complex amalgamation so $X$ is transverse to $\mathcal{C}$. It follows from definitions that $(D,D \cap X)$ collars in $(S_2,S_2\cap X)$ on both sides as required.

\label{dfn:pfolded1mfld}
    A $\mathbb{Z}_p$-folded $1$-manifold with boundary is a $1$-polyhedron $\Gamma$ and two disjoint $0$-dimensional sub-polyhedra $\text{Sing}(\Gamma)$ and $\partial \Gamma$ with a choice of orientation of the $1$-manifold $\text{Int}(\Gamma) := \Gamma \setminus (\text{Sing}(\Gamma)\sqcup \partial(\Gamma))$ such that the following properties are satisfied:

    \begin{itemize}
        \item $\text{Sing}(\Gamma)$ is a set of $p$-valent vertices which we call the \textit{singular vertices}
        \item $\partial \Gamma$ is a set of univalent vertices which we call the \textit{boundary vertices}
        \item We call $\text{Int}(\Gamma)$ the interior of $\Gamma$. Every non-compact component of $\text{Int}(\Gamma)$ is bounded by two distinct vertices in the set $\text{Sing}(\Gamma) \sqcup \partial \Gamma$ and its orientation induces an orientation on each of these vertices. The orientation of $\text{Int}(\Gamma)$ must be such that $\forall v \in \text{Sing}(\Gamma) \sqcup \partial \Gamma$ every component of $\text{Int}(\Gamma)$ cobounding $v$ induces the same orientation on it. Hence we can say that the orientation of $\text{Int}(\Gamma)$ induces an orientation of $\text{Sing}(\Gamma) \sqcup \partial \Gamma$.
    \end{itemize}

    We say that $\Gamma$ is properly embedded in a $2$-manifold $S$ with boundary $\partial S$ if $\Gamma \cap \partial S = \partial \Gamma$.

\label{dfn:meridionalintersectionpattern}
    Suppose $X$ is a $\mathbb{Z}_p$-folded surface embedded in the lens space $L(k,q)$ with a genus $1$-Heegaard decomposition $S_1\cup S_2$ adapted to $X$ in the sense of Lemma~\ref{lem:meridionaldiskintersection} and $D$ is a meridional disk of $S_2$ of the kind described in Lemma~\ref{lem:transversemeridionaldisk}. We suggestively adopt the notation that $\Gamma_{X}:= X\cap D$. By combining the facts that $(D,D\cap X)$ bicollars in $(S_2,X)$, $(\partial S_2,X\cap \partial S_2)$ collars in $(S_2,X)$ and the definition of a $\mathbb{Z}_p$-folded surface (see Definition~\ref{dfn:pfoldedsurface}) it follows that $\Gamma_{X}$ must satisfy all topological properties of a $\mathbb{Z}_p$-folded $1$-manifold with no orientation data.

    To obtain an orientation of $\text{Int}(\Gamma_{X})$ we start by fixing an orientation of $L(k,q)$ and of $D$ arbitrarily. Let $B_2$ be the compact $3$-ball obtained by cutting $S_2$ along $D$. The orientation of $S_2\subset L(k,q)$ induces an orientation on $B_2$ and hence an orientation on $\partial B_2$. The subpolyhedron $X\cap S_2$ lifts to a subpolyhedron $f^{-1}(X\cap S_2)$ and the orientation of $\text{Int}(X)\cap S_2$ lifts to an orientation of $f^{-1}(\text{Int}(X)\cap S_2)$. Let $\tilde{D}$ be the disk in $\partial B_2$ such that the map $B_2\xrightarrow{f} S_2$ restricts to an orientation preserving homeomorphism $\tilde{D}\xrightarrow{f} D$. The map $f|_{\tilde{D}}$ identifies $\tilde{\Gamma}_X := \tilde{D}\cap f^{-1}(X\cap S_2)$ with $\Gamma_{X}$. Each component of $\text{Int}(\tilde{\Gamma}_X)$ is part of the boundary of a unique component of $f^{-1}(\text{Int}(X)\cap S_2)$ and so inherits an orientation. The fact that the orientation of each component of $\text{Int}(\tilde{\Gamma}_X)$ induces a consistent orientation on $\text{Sing}(\tilde{\Gamma}_{X})$ is an immediate consequence of the fact that $\text{Sing}(\tilde{\Gamma}_{X}) \subset f^{-1}(\text{Sing}(X))$ and the requirements on the orientation of components of $\text{Int}(X)$ that cobound each singular arc as per Definition~\ref{dfn:pfoldedsurface}. This gives $(\tilde{D},\tilde{\Gamma}_X)$ the structure of a $\mathbb{Z}_p$-folded $1$-manifold properly embedded in a $2$-manifold and hence also for the pair $(D,\Gamma_X)$ via the homeomorphism $(\tilde{D},\tilde{\Gamma}_X)\xrightarrow{f} (D,\Gamma_X)$. Note that a different choice of orientation of $L(k,q),D$ possibly reverses the orientation of $\Gamma_X$ but that this is inconsequential for our proof. We call such an embedding $\Gamma_X\hookrightarrow D$ for some choice of oriented $(S_1\cup S_2,D)$ a \textit{meridional intersection pattern} of $X$.

\label{lem:simplifiedl3nqintersectionpattern}
    There exists a $\chi$-optimal $\mathbb{Z}_3$-folded surface $X$ embedded in each lens space $L(3n,q)$ with $\gcd(3n,q)=1$ and a genus $1$ Heegaard splitting $S_1\cup S_2 = L(3n,q)$ adapted to $X$ such that $X\cap S_1$ consists of a single meridional disk and there exists a meridional intersection pattern $(D,\Gamma_X)$ with the following properties.

    \begin{itemize}
        \item No component of $D\setminus \Gamma_X$ is a disk bounded by a simple closed curve component of $\Gamma_X$ or a cycle of length $2$ or $4$ in a graph component of $\Gamma_X$.
        \item No component of $\Gamma_X$ is contained in the interior of $D$.
    \end{itemize}

\label{lem:compressioninterior}
    Let $X$ be a $\chi$-optimal $\mathbb{Z}_3$-folded surface in $L(3n,q) = S_1\cup S_2$ with meridional intersection pattern $(D,\Gamma_X)$. If any component of $D\setminus \Gamma_X$ cobounds a simple closed curve component or a cycle of two or four edges in a graph component of $\Gamma_X$ then there exists another $\chi$-optimal $\mathbb{Z}_3$-folded surface $X'$ embedded in $L(3n,q)$ with the following properties.

    \begin{itemize}
        \item $X'\cap S_1$ is a subset of the meridional disks of $X\cap S_1$.
        \item $(D,D\cap X')$ bicollars in $(S_2,X'\cap S_2)$ and so $\Gamma_{X'}:= D\cap X'$ is a meridional intersection pattern as per definition~\ref{dfn:meridionalintersectionpattern}. 
        \item $|\pi_0(\text{Int}(\Gamma_{X'}))| < |\pi_0(\text{Int}(\Gamma_{X}))|$ and $|\operatorname{\text{Sing}}(\Gamma_{X'})| \leq |\operatorname{\text{Sing}}(\Gamma_{X})|$.
    \end{itemize}

\label{lem:simplifiedwithsurgieries}
    For any $d\in \mathbb{Z}^{>0}$ if there exists a $\chi$-optimal $\mathbb{Z}_3$-folded surface $X$ embedded in $L(3n,q) = S_1\cup S_2$ such that $X\cap S_1$ consists of $d$ meridional disks, then there exists a $\chi$-optimal $\mathbb{Z}_3$-folded surface $X'$ embedded in $L(3n,q)$ with a meridional intersection pattern $(D,\Gamma_{X'})$ such that:

    \begin{itemize}
        \item No component of $D\setminus \Gamma_{X'}$ is an open disk bounded by a simple closed curve component of $\Gamma_{X'}$ or a cycle of two or four edges in $\Gamma_{X'}$.
        \item $X'\cap S_1$ consists of at most $d$ meridional disks.
        \item Every component of $\Gamma{X'}$ intersects $\partial D$.

    \end{itemize}

If any component of $\Gamma_X$ is an interval whose boundary vertices are consecutive in the cyclic order of $\partial(\Gamma_X)\subset \partial D$ then it is easy to construct $I$ and $I'$ by taking another embedded interval parallel to this component of $\Gamma_X$ such that $0=|I\cap \Gamma_X| < |I'\cap \Gamma_X|=2 \leq d$. Similarly if any two consecutive vertices of $\partial(\Gamma_X)$ are cobounded by two components of $\text{Int}(\Gamma_X)$ that share a singular vertex on their boundary then it is also not hard to construct $I$ parallel to the union of these interior components such that $1=|I\cap \Gamma_X| < |I'\cap \Gamma_X|=2 \leq d$. These two simple cases are shown in Figure~\ref{fig:intervalbetterintersectionarcs}. We now assume that neither of these occurs. Let $\Gamma_X'$ be a connected component of $\Gamma_X$ with the property that the vertices of $\partial(\Gamma_X')$ form a convex set with respect to the cyclic order induced by the orientation of $\partial D$. The existence of such a $\Gamma_X'$ follows from the fact that the partition of the vertices of $\partial(\Gamma_X)$ induced by the connected components of $\Gamma_X$ is non-crossing. If $\Gamma_X$ has more than one connected component then there are at least two possible choices for $\Gamma_X'$. Since $\Gamma_X'$ is connected, every component of $D\setminus \Gamma_X'$ is an open disk and so there is a cell complex $\mathcal{C}$ of $D$ induced by $\Gamma_X'$ such that $\Gamma_X'\cup \partial D = \mathcal{C}^{(1)}$. If $\Gamma_X$ is not connected then there is a unique $2$-cell $H$ in $\mathcal{C}^{(2)}$ that contains $\Gamma_X\setminus \Gamma_X'$. If $\Gamma_X$ is connected then for the simplicity of the argument let $H$ be any of the $2$-cells whose boundary intersects $\partial D$. The orientation of $\partial D$ induces a cyclic order of the $1$-cells whose image is contained in $\partial D$. Each of these $1$-cells on the boundary is contained in precisely one $2$-cell and so this induces a cyclic order on this family of $2$-cells of $\mathcal{C}$ whose boundary intersects $\partial D$ which we denote $B$. By counting the number of $1$-cells contained in $\partial D$ it follows that $|B| = |\partial(\Gamma_X')|$. Clearly $H \in B$. If we cut the cyclic order of $B$ at $H$ then we obtain a linear order of $B\setminus \{H\} = \{B_i\}_{i=1}^{|\partial(\Gamma_X')|-1}$.

\begin{figure}
    \centering
    \includegraphics[width=0.5\linewidth]{vector-graphics/intervalbetterintersectionarcs.pdf}
    \caption{Two simple cases allowing for a Heegaard splitting adapted to $X$ such that $S_1\cap X$ consists of fewer meridional disks.}
    \label{fig:intervalbetterintersectionarcs}
\end{figure}

    Let $f:\mathcal{C}^{(2)}\rightarrow \mathbb{Z}^{>0}$ be the function that assigns to any $2$-cell the number of components of $\text{Int}(\Gamma_X')$ that are contained in its boundary.

    Let $b_i = |f^{-1}(i)\cap (B\setminus \{H\})|$, the number of $2$-cells in $B\setminus \{H\}$ that are bounded by $i$ components of $\text{Int}(\Gamma_X')$. Let $c_i = |f^{-1}(i) \setminus B|$ be the number of $2$-cells whose closure is contained in the interior of $D$ which are bounded by $i$ components of $\text{Int}(\Gamma_X')$. Let $h = f(H)$. The orientation data of $\Gamma_{X}'$ as a $\mathbb{Z}_3$-folded $1$-manifold implies that $c_i=0$ if $i$ is odd.

    The number of $2$-cells in $\mathcal{C}$ is $1+\sum_{i=1}^{\infty} \left[ b_i + c_{2i}\right]$. Each $1$-cell contained in $\text{Int}(\Gamma_X')$ is part of the boundary of two $2$-cells and so there are $\frac{h}{2}+\sum_{i=1}^{\infty} \left[\frac{2ic_{2i} +ib_i}{2} \right]$ such $1$-cells. Each $1$-cell contained in $\partial D$ is in the boundary of exactly one $2$-cell and so there are $1+\sum_{i=1}^{\infty} b_i$ such $1$-cells. The $0$-cells of $\mathcal{C}$ are either singular or boundary vertices of $\Gamma_X'$. Singular vertices appear in the boundary of three $2$-cells and so there are $\frac{h-1}{3}+\sum_{i=1}^{\infty}\frac{(i-1)b_i + 2i c_{2i}}{3}$ such vertices. Boundary vertices appear in the boundary of two $2$-cells and so there are $1+\sum_{i=1}^{\infty}b_i$ such vertices. $\mathcal{C}$ is a cell complex of this disk $D$ and so it follows that:

    \begin{multline*}
        1+\sum_{i=1}^{\infty} \left[ b_i + c_{2i}\right] - \left(\frac{h}{2}+\sum_{i=1}^{\infty} \left[\frac{2ic_{2i} +ib_i}{2} \right] + 1+\sum_{i=1}^{\infty} b_i\right) \\
         + \frac{h-1}{3}+\sum_{i=1}^{\infty}\frac{(i-1)b_i + 2i c_{2i}}{3} + 1+\sum_{i=1}^{\infty}b_i = \chi(D) = 1 \\
    \end{multline*}

    This simplifies to Equation~\ref{eq:cellcounting}.
    \begin{equation}\label{eq:cellcounting}
        \frac{4-h}{6} + \sum_{i=1}^{\infty}\left[\frac{4-i}{6}b_i +\frac{3-i}{3}c_{2i}\right] = 1
    \end{equation}

    By our assumption that neither case in Figure~\ref{fig:intervalbetterintersectionarcs} occurs it follows that $b_1=b_2=0$ and that $h\geq 2$. Since $\Gamma_X$ is of the kind described in Lemma~\ref{lem:simplifiedwithsurgieries} then it also follows that $c_2=c_4=0$. If we input these assumptions to the above equality we obtain inequality~\eqref{eq:prelimineq}

    \begin{equation}\label{eq:prelimineq}
        \sum_{i=1}^{\infty} (4-i)b_i \geq 4
    \end{equation}


    In particular it follows that $b_3 \geq 4+ \sum_{i=5}^{\infty} b_i$. Hence there exist at least three (closed) intervals in the total order of $B\setminus \{H\}$ of the form $[B_i,B_{i+k}]$ for $k\geq 1$ such that $f(B_i) = f(B_{i+k}) = 3$ and $f(B_{i+j})=4$ for all $1 \leq j<k$ if $k>1$. The family of subcomplexes that this describes are depicted in Figure~\ref{fig:b3tob3interval} and we will call this a \textit{special sequence} of length $k$. Also shown in this figure are a pair of embedded intervals $I,I'$ such that $I'\subset \partial D$ and $I$ is properly embedded in $D$ intersecting $\Gamma_X'$ transversally at points in $\text{Int}(\Gamma_X')$. In each case for an interval of this kind $[B_i,B_{i+k}]$ we have $|I'\cap \Gamma_X'| = k+2$ and $|I \cap \Gamma_X'| = k+1$. If we can show that $d\geq k+2$ then we are done. Hence we make the assumption that $d<k+2$ seeking a contradiction.

\begin{figure}
    \centering
    \includegraphics[width=0.7\linewidth]{vector-graphics/b3tob3interval.pdf}
    \caption{\textit{Special sequences} in meridional intersection patterns allowing for a reduction in the number of meridional disks.}
    \label{fig:b3tob3interval}
\end{figure}


    Because the edges of $\text{Int}(\Gamma_X')$ cobounding each vertex $v\in \text{Sing}(\Gamma_X')$ are oriented such that they induce a consistent orientation on $v$ it follows that a pair of vertices $v_1,v_2$ in $\partial(\Gamma_X')\sqcup \text{Sing}(\Gamma_X')$ have the same induced orientation if and only if any path of edges in $\Gamma_X'$ with endpoints $v_1,v_2$ is of even length. In particular if we label the boundary vertices $\partial(\Gamma_X') = \{v_i\}_{i=1}^{|\partial \Gamma_X'|}$ such that $\partial(B_i)\cap \partial(\Gamma_X') = \{v_i,v_{i+1}\}$ then since $\partial(B_i) \cap \Gamma_X'$ is a path of $f(B_i)$ edges in $\text{Int}(\Gamma_X')$ joining $v_i$ to $v_{i+1}$ we can deduce that $v_i$ has the same orientation as $v_{i+1}$ if and only if $f(B_i)$ is even. 

    In particular consider the vertices $I'\cap \Gamma_X' = \{v_i,\ldots v_{i+k+1}\}$. Without loss of generality if we assume that $v_i$ has \textit{black} orientation then $v_{i+1}$ must have \textit{white} orientation since $f(B_i) = 3$ is odd. Moreover since $f(B_{i+j})=4$ is even for all $1 \leq j<k$ it follows that (if $k>1$) the vertices $\{v_{i+1},\ldots, v_{i+k}\}$ are also white. Finally since $f(B_{i+k}) = 3$ is odd and $v_{i+k}$ is white it follows that $v_{i+k+1}$ is black. Recall from Lemma~\ref{lem:boundaryvertexpattern} that if $\sigma \in Sym(\partial \Gamma_X)$ is the permutation sending each boundary vertex to the next boundary vertex with respect to the cyclic order induced by the orientation of $\partial D$ then $\sigma^d$ preserves the orientation of $\partial \Gamma_X$. The vertices $\{v_{i+1},\ldots,v_{i+k+1}\}\subset \partial \Gamma_X$ are a closed interval in this cyclic order since they are a sub-interval of the closed interval $\{v_1,\ldots ,v_{|\partial\Gamma_X'|}\}$ (which is an interval by definition of $\Gamma_X'$). It follows that $d\geq k+1$ since if $d\leq k$ then $\sigma^d(v_i) = v_{i+d} \in \{v_{i+1},\ldots v_{i+k}\}$ does not preserve the orientation of $v_i$. Since we assumed that $d<k+2$ this implies that $d=k+1$.

    Suppose $k=1$. It follows that $d=k+1 = 2$ and so $X\cap S_1$ consists of two meridional disks of opposite orientations. From the Mayer-Vietoris sequence of $(L(3n,q),S_1,S_2)$ it follows that $[X]$ is in the kernel of $H_2(L(3n,q);\mathbb{Z}_3)\rightarrow H_1(S_1\cap S_2;\mathbb{Z}_3)$ and hence the image of $H_2(S_1;\mathbb{Z}_3)\oplus H_2(S_2;\mathbb{Z}_3)\rightarrow H_2(L(3n,q);\mathbb{Z}_3)$. But $H_2(S_1;\mathbb{Z}_3)=H_2(S_2;\mathbb{Z}_p) = 0$ and so $[X]=0$ which is a contradiction of our initial assumption. This homology argument implies that no special sequence with $k=1$ and $d<k+2$ exists in $B\setminus \{H\}$.

    Note that if $d=k+1$ and a special sequence of length $k>1$ exists then the black vertices in $\Gamma_X'$ are separated by $k$ white vertices in the total order. We call a $2$-cell $B_i\in B\setminus \{H\}$ \textit{odd} if $f(B_i)$ is odd. For $1<i<|\partial \Gamma_X'|-1$ if $B_i$ is odd then one of $\{v_i,v_{i+1}\}$ is black and so respectively one of $\{B_{i-1},B_{i+1}\}$ is odd and the other is even. If we partition the odd cells of $B\setminus \{H\}$ into subsets of adjacent cells then every subset will be a pair of adjacent cells except possibly for two singletons $\{B_1\}$ and $\{B_{|\partial \Gamma_X'|-1}\}$. 

    Since we assumed that no special sequence with $k=1$ exists it follows that each pair contains at most one cell in $f^{-1}(3)$. From this it follows that $b_3-2 \leq \sum_{i=2}^{\infty} b_{2i+1}$. A contradiction follows from the fact that $\sum_{i=2}^{\infty} b_{2i+1} \leq \sum_{i=5}^{\infty} b_{i} \leq b_3 -4$. Therefore $d\geq k+2$ and the first part of the Lemma is complete.

    Without loss of generality we can assume that $I$ and $I'$ are as above and that $|I'\cap \partial(\Gamma_X)| = d$. This is because where $|I'\cap \partial(\Gamma_X)| < d$ we can simply extend one end of $I'$ by some interval in $\partial D$ to add the required number of intersection points while extending $I$ parallel to $\partial D$ to add the same number of points in the interior of $D$. 

    $I'$ intersects the $d$ parallel meridians of $X\cap \partial S_1$ once each and so its endpoints $\partial I'$ are in the same component of $\partial S_1 \setminus X$. Let $C_1'$ be a simple closed curve on $\partial S_1$ consisting of the union of $I'$ with an interval in $\partial S_1 \setminus X$ connecting its endpoints. Since $C_1'$ intersects each meridian curve in $\partial S_1 \cap X$ in a single point we can deduce from the intersection form on the homology of the torus $\partial S_1$ that with some choice of orientation $[C_1'] = \lambda_1 + a \mu_1$ for some $a\in \mathbb{Z}$. It follows from the theory of normal arcs on a triangulation of the torus with two triangles that the ambient isotopy classes of oriented simple closed curves on the torus are classified by their homology classes. An ambient isotopy of $\partial S_1$ induces isotopies of the embedding $\partial S_1 \hookrightarrow L(3n,q)$ that fix $\partial S_1$ setwise. The PL isotopy extension theorem of~\cite{hudson1966} implies that this isotopy extends to an ambient isotopy of $L(3n,q)$ that carries $C_1'$ to any other curve on $\partial S_1$ realising the same homology class (up to a choice of orientation). For any $a\in \mathbb{Z}$ it can be shown constructively that there exists an annulus $A \subset S_1$ such that one component of $\partial A$ is the core circle $C_1$ and the other component is a curve on $\partial S_1$ which realises the homology class $\lambda_1 + a\mu_1$ with some choice of orientation. The extension of an isotopy over this annulus implies that $C_1$ is ambient isotopic to $C_1'$.

    Let $C_1''$ be the curve given by $(C_1' \setminus I')\sqcup I$. Together $I$ and $I'$ bound a disk in $D$ over which an isotopy can be performed to show that $C_1''$ is isotopic to $C_1'$. This isotopy extends to an ambient isotopy with a further application of the isotopy extension theorem.

    Following Lemma~\ref{lem:meridionaldiskintersection} it is sufficient to show that $C_1''$ is mocktransverse to $X$ in order to complete the proof. To see this note that $C_1''$ intersects $X$ at fewer than $d$ points in $\text{Int}(\Gamma_X)$ and that these intersection points are locally transverse in $D$. Since $(D,\Gamma_X)$ bicollars in $(S_2,X\cap S_2)$ by Lemma~\ref{lem:transversemeridionaldisk} it follows that $C_1''$ is locally transverse to the $2$-manifold $\text{Int}(X)$. Now recall the proof of Lemma~\ref{lem:meridionaldiskintersection} and note that $C_1''$ has the required properties of local transversality with $\text{Int}(X)$ and ambient isotopy equivalence with $C_1$ such that we can apply Lemma~\ref{lem:changingcorecircle} to obtain a new Heegaard decomposition $S_1'\cup S_2'$ of $L(3n,q)$ adapted to $X$ such that $S_1'$ is a regular neighbourhood of $C_1''$. Since $|C_1''\cap X|<d$ it follows that $S_1' \cap X$ consists of fewer than $d$ meridional disks as required.

\label{lem:unbalancedquads}
    Let $X$ be a $\chi$-optimal $\mathbb{Z}_3$-folded surface embedded in $L(3n,q) = S_1\cup S_2$ intersecting $S_1$ in a single meridional disk and with meridional intersection pattern $(D,\Gamma_X)$. Suppose for some $i$ and choice of sign $\pm$ there are two disks $C_i,C_{i\pm q} \in \pi_0(D\setminus \Gamma_X)$ with the following properties.

    \begin{itemize}
        \item $\partial C_i$ is the closure of the disjoint union of four components of $\text{Int}(\Gamma_X)$ and $I_i$.
        \item $\partial C_{i\pm q}$ is the closure of the disjoint union of two components of $\text{Int}(\Gamma_X)$ and $I_{i\pm q}$.
    \end{itemize}

    It follows that there exists another $\chi$-optimal $\mathbb{Z}_3$-folded surface $X'$ such that $X\cap S_1 = X' \cap S_1$ and $\Gamma_X' := X'\cap D$ is a meridional intersection pattern of $X'$ with at least two fewer singular vertices.

\label{dfn:boundarytripods}
    Let $(D,\Gamma)$ be a meridional intersection pattern of a $\mathbb{Z}_3$-folded surface. A connected component $\Gamma_0$ of $\Gamma$ is a \emph{boundary tripod} if it has the following properties:

    \begin{itemize}
        \item $\Gamma_0$ is the graph $K_{3,1}$ (i.e. $\partial \Gamma_0$ consists of three vertices which cone to one singular vertex in $\text{Sing}(\Gamma_0)$).
        \item $\Gamma \setminus \Gamma_0$ is contained in one connected component of $D \setminus \Gamma_0$ (equivalently $\partial \Gamma_0$ is a closed interval in the cyclically ordered set $\partial \Gamma$).
    \end{itemize}

We will prove the contrapositive. Suppose $\Gamma_X$ has no boundary tripods. We seek to show that it is not minimal with respect to the lexicographic order. 

    First, if $D\setminus \Gamma_X$ admits any disk component that cobounds a simple closed curve or a cycle of $2$ or $4$ edges in $\Gamma_X$ it follows from Lemma~\ref{lem:compressioninterior} that it is not minimal. 

    Now assume that no component of $D\setminus \Gamma_X$ is a disk bounded by a simple closed curve or a cycle of length $2$ or $4$. Let $\Gamma_X'$ be a connected component of $\Gamma_X$ such that $\partial(\Gamma_X')$ is a closed interval in the cyclically ordered set $\partial(\Gamma_X)$ and define $B$, $f:B\rightarrow \mathbb{Z}^{>0}$, $H$, $h$, $b_i$ and $c_{2i}$ for $i\in \mathbb{Z}^{>0}$ exactly as in the proof of Lemma~\ref{lem:intervalbetterintersection}. Recall Equation~\ref{eq:cellcounting} which follows from an Euler characteristic argument by counting the cells of each dimension in the cell decomposition of $D$ induced by $\Gamma_X$.

    Since $X\cap S_1$ consists of a single meridional disk every vertex of $\partial \Gamma_X$ must have the same induced orientation. It follows from this that $h$ is even and $b_{2i-1}= 0$ for all $i\in \mathbb{Z}^{>0}$. We have also made an assumption that $c_2=c_4=0$. With these constraints Equation~\ref{eq:cellcounting} yields Equation~\ref{eq:inequalitycellcount}.


    \begin{equation}
        \label{eq:inequalitycellcount}
        \begin{aligned}
            1 &= \frac{4-h}{6} + \sum_{i=1}^{\infty}\left[\frac{4-i}{6}b_i +\frac{3-i}{3}c_{2i}\right] \\
                &\leq \frac{4-h}{6} + \sum_{i=1}^{\infty} \frac{4-i}{6}b_i \\
                &\leq \frac{2}{6} + \sum_{i=1}^{\infty} \frac{4-i}{6}b_i \\
                &= \frac{2}{6} + \sum_{i=1}^{\infty} \frac{4-2i}{6}b_{2i} \\
        \end{aligned}
    \end{equation}

    Rearranging we obtain $b_2 \geq 2 + \sum_{i=3}^{\infty}b_{2i}$. Note that the cells of $f^{-1}(2)$ cannot be adjacent in the total order of $B$ described in the proof of Lemma~\ref{lem:intervalbetterintersection} since otherwise it follows from Definition~\ref{dfn:boundarytripods} that $\Gamma_X'$ is a boundary tripod. If there is at least one element of $f^{-1}(\mathbb{Z}^{\geq 6})$ between consecutive elements of $f^{-1}(2)$ then $\sum_{i=3}^{\infty}b_{2i} \geq b_2 - 1$ which is a contradiction. We deduce from this that there must be cells in $f^{-1}(2)$ that are separated by an interval which is a subset of $f^{-1}(4)$. In particular we can locate a pair of cells $C_i$ and $C_{i\pm1}$ such that $f(C_i)= 4$ and $f(C_{i\pm1}) = 2$ and apply Lemma~\ref{lem:unbalancedquads} to reduce the number of singular vertices in $\Gamma_X$. This finishes the proof of the contrapositive.

Let $X\subset L(3n,1) = S_1\cup S_2$ be $\chi$-optimal such that $X\cap S_1$ consists of a single meridional disk and $(D,\Gamma_X)$ is a meridional intersection pattern which is minimal in the sense of Lemma~\ref{lem:minimalimpliesboundarytripod} and accordingly let $\Gamma^{\psi}$ be a boundary tripod component of $\Gamma_X$. Figure~\ref{fig:boundarytripodbigon} shows how such a boundary tripod implies the existence of a disk $C$ in $\partial{B_2}\setminus \tilde{X}$ bounding a cycle of two edges in $\text{Int}(\tilde{X})$. Note that the map $q:B_2 \rightarrow S_2$ does not restrict to an embedding of $C$ and so the image of $C$ is not a $2$-compression disk of $X$. We can however use a collar of $(\partial B_2,\partial \tilde{X})$ in $(B_2,\tilde{X})$ to find a disk $C'$ parallel to $C$ in the interior of $B_2$ which embeds in $S_2$ (since the interior of $B_2$ embeds in $S_2$ as $S_2 \setminus (D\cup \partial S_2)$). A reduced $2$-compression of $X$ over the $2$-compression disk $q(C')$ yields another $\chi$-optimal $\mathbb{Z}_3$-folded surface $X'$ with a meridional intersection pattern $(D,\Gamma_{X'})$ which is some subcomplex of the meridional intersection pattern of $X$. This is because a $2$-compression of $C'$ which lies in $S_2\setminus (\partial S_2 \cup D)$ will yield a new $\mathbb{Z}_3$-folded surface with the same meridional intersection pattern, but the subsequent surface elimination step may remove some of the components of the interior of the $\mathbb{Z}_3$-folded surface that intersect $D$. Since $(X,\Gamma_X)$ already has the minimum possible number of singular vertices it follows that $\Gamma_X = \Gamma_{X'}$. Now let $\tilde{X}'$ be the lift of $X'\cap S_2$ over $B_2 \rightarrow S_2$.

