    \includegraphics[width=0.5\linewidth]{vector-graphics/boundarytripodbigon.pdf}
    \caption{A boundary tripod in a meridional intersection pattern of $L(3n,1)$ which implies the existence of a bigon $C$ in $\partial B_2 \setminus \partial \tilde{X}$ cobounding two components of $\operatorname{\text{Int}} \partial \tilde{X}$.}
    \label{fig:boundarytripodbigon}
\end{figure}

    We will now describe a non-separating non-trivial $\mathbb{Z}_3$-folded surface $Y$ embedded in $L(3(n-1),1)$ such that $\chi(Y) = \chi(X')+1$. 

    We first describe $\tilde{Y} \subset B_2$ and then the map $B_2 \rightarrow S_2$. Let $E,E' \in \pi_0(\text{Int}(\tilde{X}'))$ be the two disks such that $(\partial E \cup \partial E') \cap \partial B_2 = \partial C$ (the fact that $E,E'$ are disks follows from the reduced $2$-compression we performed on $X$ to obtain $X'$). Let $\tilde{Y}$ be the $\mathbb{Z}_3$-folded surface in $B_2$ with underlying set $\tilde{X}' \setminus E'$ such that $\tilde{Y}\setminus \overline{E}$ inherits the orientation of $\text{Int}(\tilde{X}')\setminus (E'\cup E)$ in $\tilde{X}'$ and the orientation of $E$ in $\text{Int}(\tilde{Y})$ is the opposite of its orientation in $\text{Int}(\tilde{X}')$. A simple Euler characteristic computation on a cell complex of $\tilde{X}'$ in which $E'$ is a $2$-cell and $\partial E' \cap \partial C$ is a $1$-cell yields that $\chi(\tilde{Y}) = \chi(\tilde{X}')-1+1 = \chi(\tilde{X}')$.

    If we let $q_{X'}:B_2\rightarrow S_2$ be the quotient map such that $q_{X'}(\tilde{X}') = X'\cap S_2$ then $q_{X'}(\tilde{Y})$ is no longer a $\mathbb{Z}_3$-folded surface ($q_{X'}(\tilde{Y}) \cap \partial(S_2)$ is now a closed interval not a simple closed curve). To restore this property we will now modify $q_{X'}$. First let $D_Y \subset D$ be a closed disk such that $\partial D_Y$ is the union of an interval in $\partial D$ and an interval properly embedded in $D$ which separates the boundary tripod $\Gamma^{\psi}$ from $\Gamma_{X'} \setminus \Gamma^{\psi}$ in $D$ such that $D_Y\cap \Gamma_{X'} = \Gamma_{X'} \setminus \Gamma^{\psi}$ (see Figure~\ref{fig:newD_Yboundarypattern}). Lift $D_Y$ through $q_{X'}$ to a pair of disks $D_Y^{\pm} \subset D^{\pm}$. 

\begin{figure}
    \centering
    \includegraphics[width=0.8\linewidth]{vector-graphics/newD_Yboundarypattern.pdf}
    \caption{The two boundaries $\partial \tilde{Y} \subset \partial\tilde{X}'\subset \partial B_2$ and the disks $D_Y^{\pm}\subset D_{X'}^{\pm}$.}
    \label{fig:newD_Yboundarypattern}
\end{figure}

    Let $S_2'$ be the solid torus obtained by gluing $D_Y^{+}$ and $D_Y^{-}$ on the boundary of $B_2$ via the restrictions $q_{X'}:D_Y^{\pm}\rightarrow D_Y$ and let $q_{Y}:B_2 \rightarrow S_2'$ be the corresponding quotient map. To see that $q_Y(\tilde{Y})$ is a $\mathbb{Z}_3$-folded surface properly embedded in a solid torus note that $q_Y$ now identifies $\partial \tilde{Y} \cap D_Y^{+}$ and $\partial \tilde{Y} \cap D_Y^{-}$ via an orientation reversing map of $\mathbb{Z}_3$-folded $1$-manifolds. Figure~\ref{fig:newD_Yboundarypattern} also shows how $q_Y(\tilde{Y})\cap \partial S_2'$ is a $(3(n-1),1)$-torus knot. Let $S_1'$ be another solid torus and identify $\partial S_1'$ and $\partial S_2'$ by an orientation reversing homeomorphism such that this torus knot is identified with a meridional curve of $S_1'$. The resulting space is clearly $L(3(n-1),1)$. Let $Y$ be the $\mathbb{Z}_3$-folded surface embedded in $L(3(n-1),1)$ such that $Y\cap S_2' = q_Y(\tilde{Y})$ and $Y\cap S_1'$ is a single meridional disk properly embedded in $S_1'$ cobounding this meridional curve. Now note that since $X' \cap S_2$ is homeomorphic to the quotient of $\tilde{X}'$ by the identification of $q^{-1}(\Gamma_{X'}) \cap D^+$ and $q^{-1}(\Gamma_{X'}) \cap D^-$ with $\chi(\Gamma_{X'})$ it follows that $\chi(X' \cap S_2) = \chi(\tilde{X}') - \chi(\Gamma_{X'})$. Similarly $\chi(Y \cap S_2') = \chi(\tilde{Y}) - \chi(D_Y\cap Y)$. Since $D_Y\cap Y = \Gamma_{X'} \setminus \Gamma^{\psi}$ we have $\chi(D_Y\cap Y) = \chi(\Gamma_{X'}) - \chi(\Gamma^{\psi}) = \chi(\Gamma_{X'}) - 1$ and so $\chi(Y\cap S_2') = \chi(X' \cap S_2) + 1$. Now note that since $X'\cap S_1$ and $Y\cap S_1'$ are meridional disks of the solid tori $S_1$ and $S_1'$ respectively it follows that $\chi(Y) = \chi(Y\cap S_2')+1 = \chi(X' \cap S_2) + 2 = \chi(X)+1$. 

    For notational simplicity we now set $D_{X'} := D$, $D_{X'}^{\pm} := D^{\pm}$ and $\Gamma_Y := Y\cap D_Y$. We will now prove that $X'$ is non-separating in $L(3n,1)$ if and only if $Y$ is non-separating in $L(3(n-1),1)$. 

    Let $\sim_{X'}$ be an equivalence relation on $\pi_0(\partial B_2 \setminus \partial \tilde{X}')$ generated by the following relations:

    \begin{itemize}
        \item All $x\in \pi_0(\partial B_2 \setminus \partial \tilde{X}')$ such that $x\cap q_{X'}^{-1}(\partial S_2) \neq \emptyset$ belong to a single class.
        \item If there exists a component of $B_2\setminus \tilde{X}'$ that is a cobordism of $x$ and $y$ then $x\sim_{X'} y$.
        \item If there exists $z\in \pi_0(D_{X'} \setminus \Gamma_{X'})$ such that $z$ is contained in the interior of $D_{X'}$. Let $z^+,z^- \in \pi_0(\partial B_2 \setminus \partial \tilde{X}')$ such that $z^\pm \subset D_{X'}^{\pm}$ and $q_{X'}(z^{\pm}) = z$. Then $z^+\sim_{X'} z^-$. 
    \end{itemize}

    Define $\sim_{Y}$ an equivalence relation on $\pi_0(\partial B_2 \setminus \partial \tilde{Y})$ similarly swapping $S_2$ for $S_2'$.

    Note that the fact that $X'$ is non-separating in $L(3n,1)$ is equivalent to the fact that $X'\cap S_2$ is non-separating in $S_2$. When we lift to $\tilde{X}'$ this is equivalent to the condition that every component of $B_2\setminus \tilde{X}'$ intersects $\partial B_2$ and that $\pi_0(\partial B_2 \setminus \partial \tilde{X}')/\sim_{X'}$ consists of a single class.
    Similarly $Y$ is non-separating in $L(3(n-1),1)$ if and only if the boundary of every component of $B_2\setminus \tilde{Y}$ intersects $\partial B_2$ and $\pi_0(\partial B_2 \setminus \partial \tilde{Y})/\sim_{Y}$ consists of a single class.

    Since $\tilde{Y}\subset \tilde{X}'$ and $\tilde{X}'\setminus \tilde{Y}$ consists of a single disk $E'$ separating two components of $B_2\setminus \tilde{X}'$ which both intersect $\partial B_2$ it follows that every component of $B_2\setminus \tilde{Y}$ also intersects $\partial B_2$. 

    Let $h:\pi_0(\partial B_2 \setminus \partial \tilde{X}') \rightarrow \pi_0(\partial B_2 \setminus \tilde{Y})$ be the surjective function that maps each component of $\partial B_2 \setminus \partial \tilde{X}'$ to the unique component of $\partial B_2 \setminus \partial \tilde{Y}$ that contains it. We will show that $\pi_0(\partial B_2 \setminus \partial \tilde{Y})/\sim_{Y}$ consists of a single class by proving that $x \sim_{X'} y \Leftrightarrow h(x)\sim_{Y} h(y)$ for all $x,y \in \pi_0(\partial B_2 \setminus \partial \tilde{X}')$. It is sufficient to show that this is true for the generating relations with the following observations:

    \begin{itemize}
        \item $x$ intersects $q_{X'}^{-1}(\partial(S_2))$ if and only if $h(x)$ intersects $q_{Y}^{-1}(\partial(S_2'))$. This can be verified for each component that intersects $D^{+}_{X'}\setminus D^{+}_{Y}$ and $D^{-}_{X'}\setminus D^{-}_{Y}$ by means of Figure~\ref{fig:newD_Yboundarypattern} and it is true for all other components since $q_Y^{-1}(\partial S_2') = q_{X'}^{-1}(\partial S_2)\cup (D^{+}_{X'}\setminus D^{+}_{Y})\cup (D^{-}_{X'}\setminus D^{-}_{Y})$.

        \item If there exists a component of $B_2\setminus \tilde{X}'$ that is a cobordism of $x$ and $y$, then since $\tilde{Y} \subset \tilde{X}' \Rightarrow B_2\setminus \tilde{X}' \subset B_2\setminus \tilde{Y}$ there also exists a component of $B_2\setminus \tilde{Y}$ that is a cobordism of $x$ and $y$ and hence also $h(x)$ and $h(y)$. Moreover if $h(x)$ is cobordant to $h(y)$ in $B_2\setminus \tilde{Y}$ and $x$ is not cobordant to $y$ in $B_2\setminus \tilde{X}'$ then without loss of generality $x$ must be $C$ and $y$ must be cobordant to the component $F$ of $\partial B_2 \setminus \tilde{X}'$ such that $h(C) = h(F)$ (labelled in Figure~\ref{fig:newD_Yboundarypattern}). In this case we can use the fact that $F$ and $C$ both intersect $q_{X'}^{-1}(S_2)$ to deduce that $y\sim_{X'} F \sim_{X'} x$.

        \item If $z^{\pm}$ are components of $\partial B_2 \setminus \partial \tilde{X}'$ contained in the interior of $D^{\pm}_{X'}$, then the boundary of $z$ cannot intersect $\Gamma^{\psi}$. It follows that $z^{\pm}$ are both also contained in the interior of $D^{\pm}_Y$ and persist as components of $\partial B_2 \setminus \partial \tilde{Y}$. Conversely if $z^{\pm}$ are components of $\partial B_2 \setminus \partial \tilde{Y}$ contained in the interior of $D^{\pm}_Y$ then it is trivial that they are also components of $\partial B_2 \setminus \partial \tilde{X}'$ in the interior of $D^{\pm}_{X'}$ since $D^{\pm}_Y \subset D^{\pm}_{X'}$. Since $q_Y:D^{\pm}_Y\rightarrow D_Y$ is a restriction of $q_{X'}:D^{\pm}_{X'}\rightarrow D_{X'}$ it follows that $q_{X'}(z^+) = q_{X'}(z^-) \Leftrightarrow q_{Y}(z^+) = q_{Y}(z^-)$.

    \end{itemize}

    Since every component of $B_2\setminus \tilde{Y}$ also intersects $\partial B_2$ and $\pi_0(\partial B_2 \setminus \partial \tilde{Y})/\sim_{Y}$ consists of a single class it follows that $Y\cap S_2'$ is non-separating and hence $Y$ is non-separating. This means we can take $\chi(Y) = \chi(X')+1$ to be a lower bound on $\chi_3([Y])$. Recall that since $X$ was assumed to be $\chi$-optimal it follows that $X'$ is too since it is the result of a reduced $2$-compression. Hence we have proved Equation~\eqref{eq:firstineq}.

    \begin{equation}\label{eq:firstineq}
        \chi_3(L(3(n-1),1)) \geq \chi(Y) =\chi(X')+1 = \chi_3(L(3n,1))+1
    \end{equation}



    We will now prove that $\chi_3(L(3(n+1),1)) \geq \chi_3(L(3n,1))-1$ by constructing a non-separating $\mathbb{Z}_3$-folded surface $Z \subset L(3(n+1),1)$ such that $\chi(Z) = \chi(X)-1$. This is philosophically the dual of the construction of $Y$ above. We start by selecting a point $x$ in the interior of one of the intervals in the $q_{X}^{-1}(X \cap \partial S_2)$ and considering a regular neighbourhood $N(x)$ of $x$ in $B_2$. Since $x$ lies on $\partial B_2$,  $N(x)$ is a ball such that $\partial N(x)\setminus \partial B_2$ is a disk properly embedded in $B_2$, intersected transversally by $\tilde{X}$. Let $E$ be the disk $\tilde{X}\cap N(x)$ and $E'$ be the closure of either of the disk components of $\partial N(x)\setminus \partial B_2 \setminus \tilde{X}$. Let $\tilde{Z}$ be the $\mathbb{Z}_3$-folded surface properly embedded in $B_2$ with  underlying set $\tilde{X}\cup E'$ where the orientation of $E$ has been inverted and the orientation of $E'$ is set such that $E$ and $E'$ induce a consistent orientation on their common boundary $\partial N(x)\setminus \partial B_2 \cap \tilde{X}$. A similar Euler characteristic argument to before yields that $\chi(\tilde{Z}) = \chi(\tilde{X})$. The intersection of each of these components with $\partial B_2$ is shown in Figure~\ref{fig:newD_Zboundarypattern}.

    Now let $D_0^{\pm}$ be a pair of disks contained in $q_X^{-1}(\partial S_2)$ as shown in Figure~\ref{fig:newD_Zboundarypattern} such that $\partial D_0^+ \cap \partial D_X^+$ is an interval identified with $\partial D_0^- \cap \partial D_X^-$ and $D_0^+ \cap \tilde{Z}$ and $D^-_0 \cap \tilde{Z}$ are both boundary tripods. Fix an orientation reversing homeomorphism of these boundary tripods that preserves the order of their boundary vertices. Using Alexander's trick over the three disks in the complement of these tripods we can extend the homeomorphisms $\partial D_0^+ \cap \partial D_X^+ \rightarrow \partial D_0^- \cap \partial D_X^-$ and $\tilde{Z}\cap D_0^+ \rightarrow \tilde{Z} \cap D_0^-$ to a homeomorphism $D_0^+ \rightarrow D_0^-$. Let $D_Z^{\pm} := D_0^{\pm}\cup D_X^{\pm}$ and combine the maps of $D_0^{\pm}$ and $D_X^{\pm}$ into an orientation reversing homeomorphism of $D_Z^{\pm}$. Let $S_2'$ be the solid torus obtained by a quotient of $B_2$ by identifying $D_Z^{+}$ and $D_Z^-$ in this way and let $q_Z: B_2 \rightarrow S_2'$ be the corresponding quotient map. Note that $q_Z(\tilde{Z})$ is a $\mathbb{Z}_3$-folded surface properly embedded in the solid torus $S_2'$ since the identification of $D_Z^+$ with $D_Z^-$ restricts to an orientation reversing map of $\mathbb{Z}_3$-folded $1$-manifolds $D_Z^+ \cap \tilde{Z}$ and $D_Z^- \cap \tilde{Z}$. Moreover $\partial(q_Z(\tilde{Z}))$ is a $(3(n+1),1)$-torus knot on the boundary torus $\partial S_2'$. As in the case of $Y$ above we let $S_1'$ be another oriented solid torus and glue $\partial S_1'$ and $\partial S_2'$ via an orientation reversing map such that the $\partial (q_Z(\tilde{Z}))$ is identified with a meridional curve on $\partial S_1'$. The resulting space is the lens space $L(3(n+1),1)$. Let $Z \subset L(3(n+1),1)$ be the $\mathbb{Z}_3$-folded surface such that $Z\cap S_2' = q_Z(\tilde{Z})$ and $Z\cap S_1'$ is a meridional disk properly embedded in $S_1'$ cobounding $\partial(q_Z(\tilde{Z}))$. 

    The same arguments regarding the relationship between $\chi(\tilde{X})$, $\chi(\Gamma_X)$, $\chi(X\cap S_2)$ and $\chi(X)$ with the corresponding quantities for $Z$ apply as previously in the case of $X'$ and $Y$ leading to $\chi(Z) = \chi(X)-1$. Moreover what we have just done is essentially the inverse of the construction of $Y$ from $X'$. By taking $Z\mapsto X'$, $X\mapsto Y$ and $n+1 \mapsto n$ we can use the same arguments above to show that $Z$ is non-separating in $L(3(n+1),1)$ since in particular $X'$ was non-separating if and only if $Y$ was non-separating. This implies Equation~\eqref{eq:secondineq}.

    \begin{equation}\label{eq:secondineq}
        \chi_3(L(3(n+1),1))\geq \chi(Z) = \chi(X)-1 = \chi_3(L(3n,1))-1
    \end{equation}

    Combining the inequalities in Equations~\eqref{eq:firstineq} and~\eqref{eq:secondineq} delivers the desired result that $\chi_3(L(3n,1)) = \chi_3(L(3(n-1),1))-1$.

\begin{figure}
    \centering
    \includegraphics[width=0.8\linewidth]{vector-graphics/newD_Zboundarypattern.pdf}
    \caption{The two boundaries $\partial\tilde{X} \subset \partial \tilde{Z} \subset \partial B_2$ and the disks $D_Z^{\pm} =  D_{X}^{\pm} \cup D_0^{\pm}$.}
    \label{fig:newD_Zboundarypattern}
\end{figure}

First note that due to~\cite[Theorem~6.1]{jaco20020efficienttriangulations3manifolds} it follows that any minimal triangulation $\mathcal{T}$ of $L(3n,1)$ with $n>1$ has a single vertex and it is well-known that $c(L(3,1))=2$. Let $\varphi \in H^1(L(3n,1);\mathbb{Z}_3)$ be the unique non-trivial cohomology class (up to a sign inversion). Up to normal isotopy and symmetries the intersection of $S_{\varphi}$ with each tetrahedron has four distinct types. A type $A$ tetrahedron is intersected in a quadrilateral normal disk. A type $B$ tetrahedron is intersected in a triangle normal disk. A type $C$ tetrahedron does not intersect $S_{\varphi}$ and the intersection of a type $D$ tetrahedron with $S_{\varphi}$ is homeomorphic to $K_{3,1}\times[0,1]$. These tetrahedron types are pictured in Figure~\ref{fig:tetrahedrontypes3}. Let $A, B, C, D$ be the number of type $A,B,C$ and $D$ tetrahedra in $\mathcal{T}$ respectively. We now follow identical reasoning to that used in the $\mathbb{Z}_2$ case for canonical non-orientable surfaces in~\cite{Jaco_2009}. We can partition the edges of $\mathcal{T}$ into \textit{even edges} that are not intersected by $S_{\varphi}$ and \textit{odd edges} that intersect $S_{\varphi}$ in a single point. Let the number of even edges be $\mathfrak{e}$ and the number of odd edges be $\mathfrak{o}$. Since $L(3n,1)$ is a closed $3$-manifold it follows that $\chi(S_{\varphi}) = \chi(L(3n,1) \setminus S_{\varphi})$. By pieceing together retractions for each tetrahedron type one can show that $L(3n,1) \setminus S_{\varphi}$ deformation retracts onto the subcomplex of $\mathcal{T}$ spanned by the even edges. This subcomplex has a single vertex, $\mathfrak{e}$ edges, $\frac{B+4C}{2}$ triangles and $C$ tetrahedra. Hence we deduce that $\chi(S_{\varphi}) = 1 - \mathfrak{e} + \frac{B}{2} + C$. It follows from Corollary~\ref{cor:chi3bound} that $\chi(S_{\varphi})\leq \chi_3(\varphi^*)$. Theorem~\ref{thm:l3n1norm} implies that $\chi_3(\varphi^*) = 2-n$ and hence $\chi(S_{\varphi})\leq 2-n$. Combining these two relations gives $1 - \mathfrak{e} + \frac{B}{2} + C \leq 2-n$ and hence $\mathfrak{e} \geq n-1$. Since $\varphi$ is non-trivial it follows that $\mathfrak{o}\geq 1$. Moreover since the lens spaces $L(3n,1)$ for $n>1$ have trivial integral second homology it follows that $\operatorname{\text{Sing}}(S_{\varphi}) \neq \emptyset$. Consider a triangle in $\mathcal{T}$ that intersects the singular locus of $S_{\varphi}$. If $\mathfrak{o}=1$ then all three edges of this triangle are identified such that the image of this triangle in $L(3n,1)$ is a $\mathbb{Z}_3$-crosscap $X$ (see Figure~\ref{fig:pcrosscaps}). $\mathbb{Z}_3$-crosscaps are always non-separating since they have trivial integral second homology. The Euler characteristic of a $\mathbb{Z}_3$-crosscap is $1$ which would imply that $\chi_3([X])\geq 1$, but Theorem~\ref{thm:l3n1norm} implies that $\chi_3([X]) = 2-n$. Our assumption that $n>1$ implies that $\chi_3([X])<1$ so we have a contradiction and we conclude that there must be at least two distinct odd edges. Hence we deduce that $\mathfrak{o}\geq 2$ and so $\mathfrak{e}+\mathfrak{o} \geq n+1$. Since $L(3n,1)$ is closed $\chi(L(3n,1))= 0$ and Equation~\eqref{eq:countingcellscanonical3fold} follows.

    \begin{equation}\label{eq:countingcellscanonical3fold}
        1 - \mathfrak{e} - \mathfrak{o} + 2c(L(3n,1)) - c(L(3n,1)) = \chi(L(3n,1))=0
    \end{equation}

    The required result $c(L(3n,1)) = \mathfrak{e} + \mathfrak{o} -1 \geq n$ follows immediately.
